function fuzzy(str,pat){const s=(str||"").toLowerCase();const p=(pat||"").toLowerCase();if(s.includes(p))return 100;let score=0,si=0,pi=0;while(si<s.length&&pi<p.length){if(s[si]===p[pi]){score+=10;pi++;}si++;}return pi===p.length?score:0;}
function hlMatch(name,q){if(!q)return name;const lo=name.toLowerCase(),ql=q.toLowerCase();const i=lo.indexOf(ql);if(i>=0)return name.slice(0,i)+'<mark style="background:#dcfce7;color:#166534;border-radius:3px;padding:0 2px">'+name.slice(i,i+ql.length)+"</mark>"+name.slice(i+ql.length);return name;}
function Toast({msg,type,onDone}){useEffect(()=>{const t=setTimeout(onDone,3500);return()=>clearTimeout(t);},[]);return(<div style={{position:"fixed",top:16,left:"50%",transform:"translateX(-50%)",background:type==="error"?C.dangerMid:C.p1,color:"#fff",padding:"10px 22px",borderRadius:50,fontSize:13,fontWeight:700,zIndex:9999,whiteSpace:"nowrap",fontFamily:F,maxWidth:"90vw",textAlign:"center",boxShadow:"0 8px 24px rgba(22,163,74,0.4)"}}>{msg}</div>);}
function PBtn({children,onClick,disabled,full,sm,variant="green",style}){const v={green:{background:disabled?"#86efac":C.p1,color:"#fff"},ghost:{background:"transparent",color:C.p1,border:`1.5px solid ${C.border}`},dark:{background:C.dark,color:"#fff"},danger:{background:C.danger,color:"#fff"},white:{background:"#fff",color:C.p1}};return(<button onClick={onClick} disabled={disabled} style={{border:"none",borderRadius:50,fontSize:sm?12:14,fontWeight:700,cursor:disabled?"not-allowed":"pointer",opacity:disabled?.65:1,fontFamily:F,padding:sm?"6px 14px":"13px 24px",width:full?"100%":"auto",transition:"all .15s",...v[variant],...style}}>{children}</button>);}
function Inp({label,type="text",value,onChange,placeholder}){return(<div style={{marginBottom:14}}>{label&&<div style={{fontSize:12,fontWeight:700,color:C.muted,marginBottom:5,fontFamily:F}}>{label}</div>}<input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} style={{width:"100%",padding:"12px 14px",borderRadius:14,fontSize:14,border:`1.5px solid ${C.border}`,background:C.card,color:C.text,fontFamily:F}} onFocus={e=>e.target.style.borderColor=C.p1} onBlur={e=>e.target.style.borderColor=C.border}/></div>);}
function Card({children,style}){return(<div style={{background:C.card,borderRadius:20,padding:"14px 16px",border:`1px solid ${C.border}`,marginBottom:12,...style}}>{children}</div>);}


function ShareModal({items,user,dietKey,onClose,showToast}){
const diet=dietKey?DIETS[dietKey]:null;
const total=items.reduce((s,i)=>s+(i.p||0)*(i.qty||1),0);
const lines=items.map(i=>`${i.e||"•"} ${i.name} x${i.qty||1} — $${((i.p||0)*(i.qty||1)).toFixed(2)}`).join("\n");
const msg=`🛒 CartIQ — ${user.name}'s Grocery List${diet?`\n🥗 ${diet.icon} ${diet.label} Plan`:""}\n\n${lines}\n\n💰 Total: $${total.toFixed(2)} CAD\n📍 Vancouver, BC\n\nShared from CartIQ Smart Grocery AI`;
const opts=[
{id:"whatsapp",icon:"💬",label:"WhatsApp",sub:"Send via chat",fn:()=>window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`)},
{id:"email",icon:"📧",label:"Email",sub:"Send to inbox",fn:()=>window.open(`mailto:?subject=CartIQ List from ${user.name}&body=${encodeURIComponent(msg)}`)},
{id:"link",icon:"🔗",label:"Copy Link",sub:"Shareable URL",fn:()=>{try{navigator.clipboard.writeText(`https://cartiq.app/list/${btoa(user.name+Date.now()).slice(0,12)}`).then(()=>showToast("Link copied! 🔗"));}catch{showToast("Link copied! 🔗");}}},
{id:"text",icon:"📋",label:"Copy Text",sub:"Paste anywhere",fn:()=>{try{navigator.clipboard.writeText(msg).then(()=>showToast("List copied! 📋"));}catch{showToast("List copied! 📋");}}},
];
return(<div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,.6)",zIndex:999,display:"flex",alignItems:"flex-end",justifyContent:"center"}}><div onClick={e=>e.stopPropagation()} className="slide-up" style={{background:C.card,borderRadius:"24px 24px 0 0",padding:"20px 20px 36px",width:"100%",maxWidth:430}}><div style={{width:40,height:4,background:C.border,borderRadius:2,margin:"0 auto 18px"}}/><div style={{fontFamily:FS,fontSize:18,fontWeight:800,color:C.dark,marginBottom:4}}>Share Your List 📤</div><div style={{fontSize:12,color:C.muted,marginBottom:14}}>{items.length} items · ${total.toFixed(2)} CAD{diet?` · ${diet.icon} ${diet.label}`:""}</div><div style={{background:C.pale,borderRadius:14,padding:"12px 14px",marginBottom:16,border:`1px solid ${C.border}`,maxHeight:120,overflowY:"auto"}}><div style={{fontSize:10,fontWeight:700,color:C.muted,marginBottom:5,letterSpacing:1}}>PREVIEW</div>{items.slice(0,4).map((i,idx)=>(<div key={idx} style={{fontSize:12,color:C.text,marginBottom:3}}>{i.e||"🛒"} {i.name} x{i.qty||1} — <span style={{color:C.p1,fontWeight:700}}>${((i.p||0)*(i.qty||1)).toFixed(2)}</span></div>))}{items.length>4&&<div style={{fontSize:11,color:C.muted,marginTop:3}}>+{items.length-4} more items...</div>}<div style={{fontSize:12,fontWeight:700,color:C.p1,marginTop:8,paddingTop:8,borderTop:`1px solid ${C.border}`}}>Estimated Total: ${total.toFixed(2)} CAD</div></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:12}}>{opts.map(o=>(<button key={o.id} onClick={()=>{o.fn();if(o.id!=="link"&&o.id!=="text")setTimeout(onClose,600);}} style={{background:C.pale,border:`1.5px solid ${C.border}`,borderRadius:18,padding:"14px 12px",cursor:"pointer",fontFamily:F,textAlign:"center",transition:"all .15s"}} onMouseEnter={e=>{e.currentTarget.style.borderColor=C.p1;e.currentTarget.style.background=C.light;}} onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.background=C.pale;}}><div style={{fontSize:30,marginBottom:5}}>{o.icon}</div><div style={{fontSize:13,fontWeight:700,color:C.dark}}>{o.label}</div><div style={{fontSize:10,color:C.muted,marginTop:2}}>{o.sub}</div></button>))}</div><PBtn onClick={onClose} full variant="ghost">Cancel</PBtn></div></div>);}

